           "% of the top copy (฿" + x.topA + ")\n     " + x.title.slice(0, 52);
  }).join("\n");
  var ok = ui.alert("Sold rows that look like auctions — " + name,
    "Rule: condition-adjusted price below " + Math.round(pre.ratio * 100) +
