  var data = sheet.getRange(3, 1, lastRow - 2, lastCol).getValues();
  var prefix = sheetName === MAG_SHEET ? "OWA-MAG" : "OWA-GGB";
  var reNum  = new RegExp("^" + prefix + "([A-Z])(\\d{3})");

