  try {
    var ss = SpreadsheetApp.getActiveSpreadsheet();
    var sh = ss.getSheetByName(REFRESH_LOG_SHEET);
    if (!sh) {
      sh = ss.insertSheet(REFRESH_LOG_SHEET);
      sh.getRange(1, 1, 1, 8).setValues([["Time", "Mode", "Status", "Ready", "Wrong status", "Incomplete", "Note", "Error"]]);
      sh.setFrozenRows(1);
    }
    sh.getRange(sh.getLastRow() + 1, 1, 1, 8).setValues([[new Date(), "auto", status,
      st ? st.ready : "", st ? st.wrongStatus : "", st ? st.incomplete : "", line, err]]);
  } catch (e2) { Logger.log("REFRESH LOG write failed: " + e2); }
  if (status !== "OK") {
    try {
      MailApp.sendEmail(Session.getEffectiveUser().getEmail(), "[OWARIN] Meta feed refresh " + status,
        "Status: " + status + "\n" + err + "\n\nThe previous META EXPORT is still in place unless the error says otherwise.\n" +
        "Check the REFRESH LOG tab, then run 🚀 Refresh Meta feed from the menu.");
    } catch (e3) { Logger.log("Alert email failed: " + e3); }
  }
}

